---SetWorldBossNodeInfo
---结算 世界 Boss 节点信息
function UIBattleEndLadderCompetion:SetLadderCompetionInfo()
    local data = BattleEndMgr.showData.response
    -- print("->>>UIBattleEndLadderCompetion:SetLadderCompetionInfo", table.dump(checkTable(data)))
    if IsNull(data) then return end
    --- 分数文本组件赋值
    local valueOldScore = checkNumber(data.beforeScore) -- 返回数据 历史
    local diffScore = checkNumber(data.diffScore)
    local matchResult = checkNumber(data.matchResult)   -- 1赢 2输
    local valueColor = matchResult == 1 and "#00f0ff" or "#ff0000"
    local valueSign =  matchResult == 1 and "+" or "-"
    if matchResult == 1 then
        CfUtils.FillText(self.Txt_ScoreTitle, "战斗胜利")
    else
        CfUtils.FillText(self.Txt_ScoreTitle, "战斗失败")
    end
    self.TxtScore.text = string.format("%d %s", valueOldScore, string.format("<color=%s>%s %d</color>", valueColor, valueSign, diffScore))
    
    -- 段位变化
    if data.beforeSegment ~= data.afterSegment or data.beforeSubSegment ~= data.afterSubSegment then
        self.co = cs_coroutine.start(function()
            coroutine.yield(CS.UnityEngine.WaitForSeconds(1.5))
            UIModule.OpenDialog(UIArgs(Constants.UITypeIds.LadderCompetionDanAnimDialog, {
                oldSegmentId = data.beforeSegment,
                newSegmentId = data.afterSegment,
                oldSubSegmentId = data.beforeSubSegment,
                newSubSegmentId = data.afterSubSegment
            }))
        end)
    end
end

return UIBattleEndLadderCompetion